package com.portfolio.fraud.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="fraud_analyses") public class FraudAnalysis { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="transaction_id",nullable=false) private Transaction transaction; @Column(name="risk_score",nullable=false) private int riskScore; @Enumerated(EnumType.STRING) @Column(name="risk_level",nullable=false) private RiskLevel riskLevel; @Column(nullable=false) private String action; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); @OneToMany(mappedBy="analysis",cascade=CascadeType.ALL,orphanRemoval=true) private List<FraudRuleResult> ruleResults=new ArrayList<>(); @Column(nullable=false,length=20) private String phase="ORIGINAL"; public void confirmation(){phase="CONFIRMATION";} protected FraudAnalysis(){} public FraudAnalysis(Transaction t,int s,RiskLevel l,String a){transaction=t;riskScore=s;riskLevel=l;action=a;} public void add(FraudRuleResult r){r.setAnalysis(this);ruleResults.add(r);} public int getRiskScore(){return riskScore;} public RiskLevel getRiskLevel(){return riskLevel;} public String getAction(){return action;} public Instant getCreatedAt(){return createdAt;} public List<FraudRuleResult> getRuleResults(){return List.copyOf(ruleResults);} }
